const e = $json.body;
if (
  e?.object_kind !== "merge_request" ||
  !e?.project?.path_with_namespace ||
  !e?.object_attributes?.iid ||
  !e?.object_attributes?.last_commit?.id
)
  throw Error("Invalid merge request");
return { json: { body: e, mode: "direct" } };

