parameters.jsCode:
const e = $("Prepare event").first().json.body;
const mapping = {},
  global = ["YOUR_TEAM_EMAIL"],
  emails = [
    ...(mapping[e.project.path_with_namespace] || []),
    ...global,
    e.object_attributes.last_commit.author?.email,
  ].filter(Boolean);
if (!emails.length || emails.some((x) => x.includes("YOUR_") || !/^\S+@\S+\.\S+$/.test(x)))
  throw Error("Configure recipients");
return { json: { emails: [...new Set(emails)].join(", ") } };

