=<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>CodeSnape by Quantana</title>
  <style>
    body {
      margin: 0;
      padding: 0;
      font-family: Arial, sans-serif;
    }
    table {
      border-spacing: 0;
      border-collapse: collapse;
      width: 100%;
      max-width: 960px;
      margin: 0 auto;
    }
    .container {
      width: 100%;
      max-width: 960px;
      margin: 0 auto;
    }
    .section {
      margin-bottom: 20px;
      padding: 10px;
    }
    .header {
      background-color: #f2f2f2;
      padding: 20px;
      text-align: center;
    }
    .table-container {
      background-color: #f9f9f9;
      padding: 10px;
      border-radius: 5px;
      border: 1px solid #ddd;
    }
    .report-summary-table, .table-container table {
      width: 100%;
      border-collapse: collapse;
    }
    .report-summary-table th, .report-summary-table td, 
    .table-container th, .table-container td {
      border: 1px solid #ddd;
      padding: 8px;
      text-align: left;
    }
    .report-summary-table th, .table-container th {
      background-color: #f2f2f2;
    }
    .report-summary-table tbody td, .table-container tbody td {
      background-color: #fff; /* White background for table body */
    }
    .summary-text {
      color: #1D4ED8;
    }
    .risk-low {
      color: #6B7280;
    }
    .risk-medium {
      color: #F59E0B;
    }
    .risk-high {
      color: #EF4444;
    }
    code {
      background-color: #f4f4f4;
      padding: 2px 4px;
      border-radius: 3px;
      font-family: "Courier New", Courier, monospace;
    }
  </style>
</head>
<body>
  <table class="container">
    <tr>
      <td class="header">
        <h1>CodeSnape by Quantana</h1>
      </td>
    </tr>
    <tr>
      <td>
        <table class="report-summary-table">
          <tr>
            <td><strong>Summary</strong></td>
            <td class="summary-text">{{ $('AI Agent').item.json.output.Summary }}</td>
            <td><strong>Risk Level</strong></td>
  <td style="
    font-weight: bold;
    font-size: 1.5em;
    color: 
      {{ $('AI Agent').item.json.output.RiskLevel.replace(/<\/?b>/g, '') === 'Low' ? '#6B7280' : 
         $('AI Agent').item.json.output.RiskLevel.replace(/<\/?b>/g, '') === 'Medium' ? '#F59E0B' : 
         '#EF4444' }};
    ">
    {{ $('AI Agent').item.json.output.RiskLevel.replace(/<\/?b>/g, '') }}
  </td>
          </tr>
          <tr>
            <td><strong>Project Name</strong></td>
            <td>{{ $('Prepare event').first().json.body.project.name }}</td>
            <td><strong>User Name</strong></td>
            <td>{{ $('Prepare event').first().json.body.user.name }}</td>
          </tr>
          <tr>
            <td><strong>Created Date</strong></td>
            <td colspan="3">
              {{ $('Prepare event').first().json.body.object_attributes.created_at }} (UTC)
              <br />
{{ new Date($('Prepare event').first().json.body.object_attributes.created_at).toLocaleString('en-IN', { 
  timeZone: 'Asia/Kolkata', 
  day: '2-digit', 
  month: 'short', 
  year: 'numeric', 
  hour: '2-digit', 
  minute: '2-digit', 
  second: '2-digit', 
  hour12: true 
}).replace(',', '') }} (IST)
              </span>
            </td>
          </tr>
        </table>
      </td>
    </tr>
    <tr>
      <td class="section">
        <h2>Recommendations</h2>
        <table class="table-container">
          <thead>
            <tr>
              <th>Recommendation</th>
              <th>Code Snippet</th>
            </tr>
          </thead>
          <tbody>
            {{ $('AI Agent').item.json.output.Recommendations.map(rec => `
              <tr>
                <td>${rec.Recommendation}</td>
                <td><code>${rec.CodeSnippet}</code></td>
              </tr>
            `).join('') }}
          </tbody>
        </table>
      </td>
    </tr>
    <tr>
      <td class="section">
        <h2>Test Cases</h2>
        <table class="table-container">
          <thead>
            <tr>
              <th>Test For</th>
              <th>Steps</th>
              <th>Expected Outcome</th>
            </tr>
          </thead>
          <tbody>
            {{ $('AI Agent').item.json.output.TestCases.map(test => `
              <tr>
                <td>${test.TestFor}</td>
                <td>${test.Steps}</td>
                <td>${test.ExpectedOutcome}</td>
              </tr>
            `).join('') }}
          </tbody>
        </table>
      </td>
    </tr>
    <tr>
      <td class="section">
        <h2>Issues</h2>
        <table class="table-container">
          <thead>
            <tr>
              <th>File</th>
              <th>Potential Issue</th>
              <th>Severity</th>
            </tr>
          </thead>
          <tbody>
            {{ $('AI Agent').item.json.output.Issues.map(issue => `
              <tr>
                <td>${issue.File}</td>
                <td>${issue.PotentialIssue}</td>
                <td>${issue.Severity}</td>
              </tr>
            `).join('') }}
          </tbody>
        </table>
      </td>
    </tr>
    <tr>
      <td class="section">
        <h2>Diff Table</h2>
        <table class="table-container">
          <thead>
            <tr>
              <th>Line</th>
              <th>Before</th>
              <th>After</th>
            </tr>
          </thead>
          <tbody>
            {{ $('AI Agent').item.json.output.DiffTable.Changes.map(change => `
              <tr>
                <td>${change.Line}</td>
                <td><code>${change.Before}</code></td>
                <td><code>${change.After}</code></td>
              </tr>
            `).join('') }}
          </tbody>
        </table>
      </td>
    </tr>
    <tr>
      <td class="section">
        <h2>URL</h2>
        <p><a href="{{ $('Extract Diff').item.json.web_url }}" target="_blank">{{ $('Extract Diff').item.json.web_url }}</a></p>
      </td>
    </tr>
<tr><td>Email Generated by CodeSnape from <a href=“https://quantana.com.au/ai”>Quantana</a> </td></tr>
  </table>
</body>
</html>
